using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;
namespace ZenForms.Core { [ToolboxBitmap(typeof(GroupBox))][System.ComponentModel.Category("ZenForms Modern Controls")] public class ZenGroupBox:GroupBox { public int CornerRadius{get;set;}=10; public ZenGroupBox(){ForeColor=ZenTheme.Foreground;Font=new Font("Segoe UI Semibold",9.5f);BackColor=Color.Transparent;Padding=new Padding(12,8,12,10);SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);} protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;Size text=TextRenderer.MeasureText(Text,Font);Rectangle r=new Rectangle(1,text.Height/2,Width-3,Height-text.Height/2-2);using(GraphicsPath p=ZenButtonBase.RoundPath(r,CornerRadius)){using(Pen pen=new Pen(ZenTheme.Border))e.Graphics.DrawPath(pen,p);}Rectangle tr=new Rectangle(12,0,text.Width+8,text.Height);using(SolidBrush b=new SolidBrush(Parent==null?ZenTheme.Background:Parent.BackColor))e.Graphics.FillRectangle(b,tr);TextRenderer.DrawText(e.Graphics,Text,Font,new Rectangle(16,0,text.Width,text.Height),ZenTheme.Foreground,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);} } } 
